      ...requiredViews.filter((page) => !viewed.has(page)).map((page) => `view page ${page}`),
      ...(!isTextOnly ? crops.filter((crop) => !cropped.has(crop.id)).map((crop) => `inspect crop ${crop.id}`) : []),
    ];
