      } else if (review.messages.length === 1 && /Required view_source pages: 1\./.test(prompt)) {
        content = [{ type: "toolCall", id: "view-ui", name: "view_source", arguments: { page: 1 } }]; stopReason = "toolUse";
      }
      return { role: "assistant", content, stopReason, api: model.api, provider: model.provider, model: model.id, timestamp: Date.now(), usage: { input: 100, output: 100, cacheRead: 0, cacheWrite: 0 } };
    } },
    hasUI: true,
    isIdle: () => true,
    abort: async () => {},
    sessionManager: {
      getSessionId: () => "scholar-ui-contract",
      getSessionFile: () => join(root, "session.jsonl"),
      getEntries: () => branch,
      getBranch: () => branch,
    },
    ui: {
      notify: (message, level) => notifications.push({ message, level }),
      setStatus: () => {},
      setWorkingMessage: () => {},
      setEditorText: () => {},
      setEditorComponent: (factory) => { editorFactory = factory; },
      getEditorComponent: () => editorFactory,
      editor: async () => { throw new Error("Exam must not use the Pi editor"); },
      confirm: async () => true,
      select: async (_title, options) => options[0],
    },
  };
  const extension = loaded.extensions[0];
  for (const handler of extension.handlers.get("session_start") || []) {
    await handler({}, context);
  }
  const command = extension.commands.get("scholar");
  await command.handler(`obsidian "${obsidian}"`, context);
  await command.handler(`library "${library}"`, context);
  await command.handler('open "Synthetic Scholar Book.pdf"', context);

